                  "type": "string",
                  "label": "Version",
                  "unit": "identifier"
                },
                "promptVersion": {
                  "type": "string",
                  "label": "Prompt Version",
                  "unit": "identifier"
                },
                "settingsVersion": {
                  "type": "string",
                  "label": "Settings Version",
                  "unit": "identifier"
                }
              }
            },
            "cases": {
              "type": "array",
              "label": "Fixed business cases and reference answers",
              "items": {
                "type": "object",
                "label": "Cases record",
                "fields": {
                  "id": {
                    "type": "string",
                    "label": "Id",
                    "unit": "identifier"
                  },
                  "label": {
                    "type": "string",
                    "label": "Label"
                  },
                  "source": {
                    "type": "string",
                    "label": "Source"
                  }
                }
              },
              "keyFields": [
                "id"
              ]
            },
            "repetitions": {
              "type": "number",
              "label": "Repetitions",
              "integer": true,
              "minimum": 1,
              "maximum": 100
            },
            "randomizationSeed": {
              "type": "number",
              "label": "Randomization Seed",
              "integer": true,
              "minimum": 0,
              "maximum": 4294967295
            },
            "observations": {
              "type": "array",
              "label": "Retained executions and separate outcome scores",
              "items": {
                "type": "object",
                "label": "Observations record",
                "fields": {
                  "id": {
                    "type": "string",
                    "label": "Id",
                    "unit": "identifier"
                  },
                  "caseId": {
                    "type": "string",
                    "label": "Case Id",
                    "unit": "identifier"
                  },
                  "configurationId": {
                    "type": "string",
                    "label": "Configuration Id",
                    "unit": "identifier"
                  },
                  "repetition": {
                    "type": "number",
                    "label": "Repetition",
                    "integer": true,
                    "minimum": 1,
                    "maximum": 100
                  },
                  "status": {
                    "type": "string",
                    "label": "Status",
                    "options": [
                      "observed",
                      "failed",
                      "missing"
                    ]
                  },
                  "outcomes": {
                    "type": "object",
                    "label": "Outcomes",
                    "fields": {
                      "evidence-handling": {
                        "type": "number",
                        "label": "Evidence handled correctly (0–100)",
                        "optional": true,
                        "minimum": 0,
                        "maximum": 100
                      },
                      "task-completion": {
                        "type": "number",
                        "label": "Correct useful report (0–100)",
                        "optional": true,
                        "minimum": 0,
                        "maximum": 100
                      },
                      "unsupported-claims": {
                        "type": "number",
                        "label": "Unsupported claims per report",
                        "optional": true,
                        "minimum": 0,
                        "maximum": 10
                      }
                    }
                  },
                  "source": {
                    "type": "string",
                    "label": "Source"
                  }
                }
              },
              "keyFields": [
                "id"
              ]
            }
          }
        },
        "groups": [
          {
            "id": "experiment-basis",
            "label": "Experiment basis",
            "question": "Which fixed system, scope and execution plan apply?",
            "subtabs": [
              {
                "id": "basis",
                "label": "System and scope",
                "fieldPaths": [
                  "/scope",
                  "/system",
                  "/randomizationSeed",
                  "/repetitions"
                ]
              }
            ]
          },
          {
            "id": "reference-cases",
            "label": "Reference cases",
            "question": "Which independent business tasks supply the comparison?",
            "subtabs": [
              {
                "id": "cases",
                "label": "Reference cases",
                "fieldPaths": [
                  "/cases"
                ]
              }
            ]
          },
          {
            "id": "execution-records",
            "label": "Scored outputs",
            "question": "What observations and failures came from the planned executions?",
            "subtabs": [
              {
                "id": "observations",
                "label": "Scored outputs",
                "fieldPaths": [
                  "/observations"
                ]
              }
            ]
          }
        ]
      }
