{
  "format": "screen-process-improvements/1",
  "module": {
    "id": "ai-report-screening",
    "version": "1.0.0",
    "title": "Screen report improvements",
    "question": "Which report changes warrant a separate confirmation experiment?",
    "description": "A bounded experiment with paired reporting cases and repeated outputs. Results describe these supplied observations, not all future AI reports.",
    "boundary": "Diagnostic configurations can deliberately omit required controls. A promising experimental configuration is not authorization to deploy it or cut staff.",
    "factors": [
      {
        "id": "metric-definition",
        "label": "Define net direct ad bookings",
        "minus": "Existing wording",
        "plus": "Explicit metric and exclusions"
      },
      {
        "id": "insufficient-evidence",
        "label": "Disclose insufficient evidence",
        "minus": "No explicit instruction",
        "plus": "State what the evidence cannot establish"
      },
      {
        "id": "source-references",
        "label": "Reference source records",
        "minus": "No record references requested",
        "plus": "Cite supporting record identifiers"
      },
      {
        "id": "report-sections",
        "label": "Separate findings from explanations",
        "minus": "Free-form narrative",
        "plus": "Facts, calculation, conclusion, limitations"
      },
      {
        "id": "seller-mapping",
        "label": "Validated seller attribution",
        "minus": "Original attribution view",
        "plus": "Validated seller mapping"
      },
      {
        "id": "order-completeness",
        "label": "Accepted-order population",
        "minus": "Original customer/payment join",
        "plus": "Accepted orders reconciled independently"
      },
      {
        "id": "logical-order-id",
        "label": "Logical order identity",
        "minus": "Raw event rows",
        "plus": "One logical order with its revisions"
      },
      {
        "id": "period-cutoff",
        "label": "Period and freshness metadata",
        "minus": "Implicit period",
        "plus": "Explicit reporting period and source cutoff"
      }
    ],
    "design": {
      "kind": "plackett-burman-12"
    },
    "outcomes": [
      {
        "id": "evidence-handling",
        "label": "Evidence handled correctly (0–100)",
        "direction": "maximize",
        "minimum": 0,
        "maximum": 100,
        "minimumAcceptable": 90
      },
      {
        "id": "task-completion",
        "label": "Correct useful report (0–100)",
        "direction": "maximize",
        "minimum": 0,
        "maximum": 100,
        "minimumAcceptable": 85
      },
      {
        "id": "unsupported-claims",
        "label": "Unsupported claims per report",
        "direction": "minimize",
        "minimum": 0,
        "maximum": 10,
        "minimumAcceptable": 0
      }
    ],
    "assumptions": [
      "Every configuration receives the same business task and is scored against the same independent reference answer for each case.",
      "Instruction and evidence supply may vary. Known accounting, identity, scope and access rules remain mandatory outside this diagnostic experiment.",
      "Cases are the units of business variation; repeated outputs are not additional independent business cases.",
      "Screening main effects can include interactions. Confirm the selected combination before using it on fresh cases.",
      "The held-out case set is reserved before selection and tuning. Changing that policy requires a new validation set.",
      "All bundled observations are fictional teaching inputs. They do not demonstrate actual model performance."
    ],
    "metadata": {
      "fictional": true,
      "referenceMetric": "Net direct ad bookings",
      "scoringProtocol": "ai-report-rubric/1",
      "scoringRubric": {
        "id": "ai-report-rubric/1",
        "unit": "One completed output against one independent reference case",
        "outcomes": [
          {
            "id": "evidence-handling",
            "meaning": "Human-assigned 0–100 score for respecting the available evidence, referencing relevant records, retaining scope/cutoff qualifications and distinguishing unsupported explanation from an established finding.",
            "anchors": {
              "0": "Misrepresents evidence or conceals a decisive gap",
              "50": "Partially preserves evidence qualifications",
              "100": "All rubric evidence-handling criteria satisfied"
            }
          },
          {
            "id": "task-completion",
            "meaning": "Human-assigned 0–100 score for a useful answer to the fixed reporting task: correct net direct bookings and target comparison with an auditable bridge and an appropriately bounded conclusion.",
            "anchors": {
              "0": "No useful supported answer",
              "50": "Incomplete or materially incorrect answer",
              "100": "Complete correct useful report"
            }
          },
          {
            "id": "unsupported-claims",
            "meaning": "Count of distinct affirmative claims unsupported by the reference evidence, such as attributing the reconciled total to stronger prospecting."
          }
        ],
        "abstentionExample": {
          "explanation": "When the supplied view cannot establish the bookings total, an explicit, correct insufficiency statement can score 100 for evidence handling and 0 for task completion. Appropriate abstention is not useful task completion."
        },
        "thresholdPolicy": "Each declared threshold applies to the equally weighted mean across supplied business cases; this is not a worst-case guarantee or a future error-rate bound.",
        "responsibility": "Independent reference reconciliation and consistent scoring are supplied human judgments. The SDK validates and analyzes the entered scores; it does not read or grade AI prose."
      },
      "referenceBridge": {
